 int dp(float n){return(int)(n*d+.5f);}boolean zh(){return"zh".equals(getResources().getConfiguration().getLocales().get(0).getLanguage());}String l(String cn,String en){return zh()?cn:en;}GradientDrawable shape(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}GradientDrawable outline(int c,float r,int stroke){GradientDrawable g=shape(c,r);g.setStroke(dp(1),stroke);return g;}TextView tv(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER_VERTICAL);return v;}ImageView icon(int res){ImageView v=new ImageView(this);v.setImageResource(res);v.setPadding(dp(11),dp(11),dp(11),dp(11));return v;}
 @Override public void onCreate(Bundle b){super.onCreate(b);d=getResources().getDisplayMetrics().density;getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);ReminderStore.load(this);note=ReminderStore.items.isEmpty()?new ReminderStore.Reminder(System.currentTimeMillis()):ReminderStore.items.get(0);note.pinned=true;build();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);}
