 void addTodoRow(ReminderStore.Todo item){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),0,dp(12),0);TextView box=tv(item.done?"✓":"",14,Color.WHITE);box.setGravity(Gravity.CENTER);box.setTypeface(null,Typeface.BOLD);box.setBackground(item.done?shape(GREEN,4):outline(Color.WHITE,4,Color.rgb(156,163,175)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(22),dp(22));bp.rightMargin=dp(9);row.addView(box,bp);EditText value=new EditText(this);value.setText(item.text);value.setSingleLine();value.setLongClickable(false);value.setTextIsSelectable(false);value.setTextSize(14);value.setTextColor(item.done?MUTED:TEXT);value.setPadding(0,0,0,0);value.setBackgroundColor(Color.TRANSPARENT);if(item.done)value.setPaintFlags(value.getPaintFlags()|Paint.STRIKE_THRU_TEXT_FLAG);row.addView(value,new LinearLayout.LayoutParams(0,dp(48),1));SwipeDeleteLayout swipe=new SwipeDeleteLayout(this,row,()->deleteTodo(item));swipe.setSwipeEnabled(!item.text.trim().isEmpty());swipe.setReorderEnabled(!item.text.trim().isEmpty());swipe.setReorderListener(new SwipeDeleteLayout.ReorderListener(){public void started(){startReorder(item,swipe);}public void moved(float deltaY){moveReorder(item,swipe,deltaY);}public void ended(){endReorder(swipe);}});value.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){item.text=s.toString();boolean enabled=!item.text.trim().isEmpty();swipe.setSwipeEnabled(enabled);swipe.setReorderEnabled(enabled);dirty=true;}public void afterTextChanged(Editable e){}});box.setOnClickListener(v->{item.done=!item.done;dirty=true;render();});todos.addView(swipe,new LinearLayout.LayoutParams(-1,dp(48)));}
 void startReorder(ReminderStore.Todo item,SwipeDeleteLayout view){draggedTodo=item;dragStartIndex=note.todos.indexOf(item);dragTargetIndex=dragStartIndex;if(dragStartIndex<0)return;GradientDrawable border=shape(Color.TRANSPARENT,7);border.setStroke(dp(2),BLUE);view.setForeground(border);view.setElevation(dp(8));view.animate().scaleX(1).scaleY(1.025f).setDuration(96).setInterpolator(new android.view.animation.OvershootInterpolator(1.6f)).start();}
 void moveReorder(ReminderStore.Todo item,SwipeDeleteLayout view,float deltaY){int count=note.todos.size();if(count<2||item!=draggedTodo)return;float rowHeight=dp(48),limit=rowHeight*.55f;float damped=Math.abs(deltaY)<limit?deltaY*.58f:deltaY-Math.signum(deltaY)*limit*.42f;float desiredTop=Math.max(0,Math.min((count-1)*rowHeight,dragStartIndex*rowHeight+damped)),position=desiredTop/rowHeight;int target=deltaY>=0?(int)Math.floor(position+.55f):(int)Math.ceil(position-.55f);target=Math.max(0,Math.min(count-1,target));if(target!=dragTargetIndex){dragTargetIndex=target;for(int i=0;i<count;i++){View child=todos.getChildAt(i);if(child==view)continue;float shift=target>dragStartIndex&&i>dragStartIndex&&i<=target?-rowHeight:target<dragStartIndex&&i>=target&&i<dragStartIndex?rowHeight:0;child.animate().translationY(shift).setDuration(120).start();}}view.setTranslationY(desiredTop-dragStartIndex*rowHeight);}
