 void addTodoInput(){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),0,dp(8),0);TextView box=tv("",14,MUTED);box.setBackground(outline(Color.WHITE,4,Color.rgb(209,213,219)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(22),dp(22));bp.rightMargin=dp(9);row.addView(box,bp);EditText input=new EditText(this);input.setSingleLine();input.setTextSize(14);input.setTextColor(TEXT);input.setHintTextColor(Color.rgb(190,195,202));input.setHint(note.todos.isEmpty()?l("点击添加第一条待办","Add first item"):l("点击添加新的待办","Add another Todo"));input.setPadding(0,0,0,0);input.setBackgroundColor(Color.TRANSPARENT);row.addView(input,new LinearLayout.LayoutParams(0,dp(48),1));final ReminderStore.Todo[] promoted={null};SwipeDeleteLayout swipe=new SwipeDeleteLayout(this,row,()->{if(promoted[0]!=null&&!promoted[0].text.trim().isEmpty())deleteTodo(promoted[0]);});swipe.setSwipeEnabled(false);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){String text=s.toString();if(promoted[0]==null&&!text.trim().isEmpty()&&note.todos.size()<50){promoted[0]=new ReminderStore.Todo(text,false);note.todos.add(promoted[0]);dirty=true;addTodoInput();}else if(promoted[0]!=null)promoted[0].text=text;swipe.setSwipeEnabled(!text.trim().isEmpty());}public void afterTextChanged(Editable e){}});box.setOnClickListener(v->{if(promoted[0]!=null&&!promoted[0].text.trim().isEmpty()){promoted[0].done=!promoted[0].done;dirty=true;render();}});todos.addView(swipe,new LinearLayout.LayoutParams(-1,dp(48)));}void deleteTodo(ReminderStore.Todo item){deletedAt=note.todos.indexOf(item);if(deletedAt<0)return;deleted=note.todos.remove(deletedAt);dirty=true;render();snack(l("已删除“","Deleted “")+shorten(deleted.text)+"”");}String shorten(String s){return s.length()>12?s.substring(0,12)+"…":s;}
 View bottom(){LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),dp(10),dp(16),dp(10));bar.setBackgroundColor(Color.WHITE);TextView save=tv("Pin",15,Color.WHITE);save.setGravity(Gravity.CENTER);save.setTypeface(null,Typeface.BOLD);save.setBackground(shape(BLUE,7));save.setOnClickListener(v->save());bar.addView(save,new LinearLayout.LayoutParams(0,dp(48),1));ImageView del=new ImageView(this);del.setImageResource(R.drawable.delete_icon);del.setScaleType(ImageView.ScaleType.FIT_XY);del.setBackground(shape(Color.TRANSPARENT,7));del.setClipToOutline(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(48),dp(48));lp.leftMargin=dp(14);bar.addView(del,lp);del.setOnClickListener(v->clear());return bar;}
 boolean hasCurrentContent(){if("text".equals(note.type))return!note.text.isEmpty();for(ReminderStore.Todo t:note.todos)if(!t.text.isEmpty())return true;return false;}void clearTitle(){capture();String old=note.title;if(old.isEmpty())return;note.title="";dirty=true;render();snack(l("已清空标题","Title cleared"),()->{note.title=old;dirty=true;render();});}void clearContent(){capture();if("text".equals(note.type)){String old=note.text;if(old.isEmpty())return;note.text="";dirty=true;render();snack(l("已清空内容","Content cleared"),()->{note.text=old;dirty=true;render();});}else{java.util.ArrayList<ReminderStore.Todo> old=new java.util.ArrayList<>();for(ReminderStore.Todo t:note.todos)old.add(new ReminderStore.Todo(t.text,t.done));if(old.isEmpty())return;note.todos.clear();dirty=true;render();snack(l("已清空待办","Todos cleared"),()->{note.todos.clear();note.todos.addAll(old);dirty=true;render();});}}void capture(){if(title!=null)note.title=title.getText().toString();if(content!=null)note.text=content.getText().toString();}boolean valid(){if(!note.title.trim().isEmpty())return true;if("text".equals(note.type))return!note.text.trim().isEmpty();for(ReminderStore.Todo t:note.todos)if(!t.text.trim().isEmpty())return true;return false;}void save(){capture();if(!valid()){Toast.makeText(this,l("请先输入标题或内容","Enter a title or content first"),Toast.LENGTH_SHORT).show();return;}note.title=note.title.trim();note.text=note.text.trim();note.todos.removeIf(t->t.text.trim().isEmpty());note.updated=System.currentTimeMillis();note.pinned=true;ReminderStore.items.clear();ReminderStore.items.add(note);ReminderStore.save(this);dirty=false;Toast.makeText(this,l("Pin 成功，已固定到通知栏","Pinned to notifications"),Toast.LENGTH_SHORT).show();finishAndRemoveTask();}void clear(){capture();ReminderStore.Reminder old=note;String selectedType=old.type;ReminderStore.items.clear();ReminderStore.save(this);note=new ReminderStore.Reminder(System.currentTimeMillis());note.type=selectedType;dirty=false;render();snack(l("已删除，可撤销","Deleted"),()->{String currentType=note.type;note=old;note.type=currentType;ReminderStore.items.clear();ReminderStore.items.add(note);ReminderStore.save(this);dirty=false;render();});}
 void snack(String msg){ReminderStore.Todo item=deleted;int at=deletedAt;snack(msg,()->{if(item!=null){note.todos.add(Math.min(at,note.todos.size()),item);deleted=null;render();}});}void snack(String msg,Runnable undoAction){if(hide!=null)root.removeCallbacks(hide);View old=root.findViewById(R.id.snackbar);if(old!=null)root.removeView(old);LinearLayout s=new LinearLayout(this);s.setId(R.id.snackbar);s.setGravity(Gravity.CENTER_VERTICAL);s.setPadding(dp(14),0,dp(8),0);s.setBackground(shape(Color.rgb(24,24,27),8));TextView ok=tv("✓",14,Color.WHITE);ok.setGravity(Gravity.CENTER);ok.setBackground(shape(GREEN,16));s.addView(ok,new LinearLayout.LayoutParams(dp(28),dp(28)));TextView m=tv(msg,13,Color.WHITE);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,-1,1);mp.leftMargin=dp(10);s.addView(m,mp);TextView undo=tv(l("撤销","Undo"),14,Color.WHITE);undo.setTypeface(null,Typeface.BOLD);undo.setGravity(Gravity.CENTER);undo.setOnClickListener(v->{root.removeCallbacks(hide);if(s.getParent()!=null)root.removeView(s);undoAction.run();});s.addView(undo,new LinearLayout.LayoutParams(dp(56),-1));FrameLayout.LayoutParams fp=new FrameLayout.LayoutParams(-1,dp(54),Gravity.BOTTOM);fp.setMargins(dp(16),0,dp(16),dp(82));root.addView(s,fp);hide=()->{if(s.getParent()!=null)root.removeView(s);deleted=null;};root.postDelayed(hide,2000);}
 @Override public void onBackPressed(){capture();if(!dirty){super.onBackPressed();return;}new AlertDialog.Builder(this).setTitle(l("放弃当前编辑？","Discard changes?")).setMessage(l("当前内容尚未保存，放弃后将丢失所有修改。","Your unsaved changes will be lost.")).setNegativeButton(l("取消","Cancel"),null).setPositiveButton(l("放弃","Discard"),(d,w)->super.onBackPressed()).show();}
